//! Real device frames for the simulator: iPhones, iPads, Pixels and Galaxys
//! from https://github.com/jonnyjackson26/device-frames-media.
//!
//! The catalog (device_frame_catalog.rs, generated by
//! `assets/devices/gen_frame_catalog.py`) holds each device's measurements:
//! its screen in points, safe areas, and where the screen sits in the frame
//! image. The frame PNG and its screen mask are downloaded the first time a
//! device is used and kept in the user's cache directory.

use std::path::{Path, PathBuf};

use crate::device_profiles::DeviceProfile;

pub use crate::device_frame_catalog::FRAME_DEVICES;

const BASE_URL: &str =
    "https://raw.githubusercontent.com/jonnyjackson26/device-frames-media/main/device-frames-output/";

/// One color of a device.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Variant {
    /// kebab-case, as in the source index (`cosmic-orange`).
    pub id: &'static str,
    pub name: &'static str,
    /// `Category/Model/Color` under the source's output folder.
    pub path: &'static str,
    pub color: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FrameDevice {
    /// `iphone-17-pro`, `pixel-9-pro`, `ipad-pro-13-m4-m5`…
    pub id: &'static str,
    pub name: &'static str,
    /// `ios` or `android`.
    pub os: &'static str,
    /// `phone` or `tablet`.
    pub kind: &'static str,
    /// Screen size in points, the way the frame image stands.
    pub points: (i32, i32),
    /// Safe area (top, bottom) in points.
    pub safe: (i32, i32),
    /// Screen rectangle in the frame image (x, y, w, h), in pixels.
    pub screen: (i32, i32, i32, i32),
    /// Frame image size in pixels.
    pub frame: (i32, i32),
    pub variants: &'static [Variant],
}

impl FrameDevice {
    /// Frame pixels per point.
    fn pixels_per_point(&self) -> f32 {
        self.screen.2 as f32 / self.points.0 as f32
    }

    /// The simulator profile: the screen in points, the frame measured in
    /// points too, so a host scale of 1 shows the device at its real size.
    pub fn profile(&self) -> DeviceProfile {
        let k = self.pixels_per_point();
        let pt = |px: i32| (px as f32 / k).round() as i32;
        let (sx, sy, _, _) = self.screen;
        DeviceProfile {
            name: self.name,
            width: self.points.0,
            height: self.points.1,
            safe_top: self.safe.0,
            safe_bottom: self.safe.1,
            safe_left: 0,
            safe_right: 0,
            scale: k,
            frame_screen_x: pt(sx),
            frame_screen_y: pt(sy),
            frame_screen_w: self.points.0,
            frame_screen_h: self.points.1,
            frame_w: pt(self.frame.0),
            frame_h: pt(self.frame.1),
        }
    }

    /// The color `id` (or name), else the first one.
    pub fn variant(&self, id: Option<&str>) -> &'static Variant {
        let wanted = id.map(|s| s.trim().to_lowercase().replace(' ', "-"));
        wanted
            .and_then(|w| self.variants.iter().find(|v| v.id == w))
            .unwrap_or(&self.variants[0])
    }
}

/// A device by id (`iphone-17-pro`), case- and separator-insensitive, so
/// `iPhone 17 Pro` and `iphone17pro` work too.
pub fn lookup(name: &str) -> Option<&'static FrameDevice> {
    let key = |s: &str| s.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_lowercase();
    let wanted = key(name);
    FRAME_DEVICES.iter().find(|d| key(d.id) == wanted || key(d.name) == wanted)
}

/// Where downloaded frames are kept: the OS cache directory, under
/// `mocida/device-frames`.
pub fn cache_dir() -> PathBuf {
    let env = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty()).map(PathBuf::from);
    let base = if cfg!(target_os = "macos") {
        env("HOME").map(|h| h.join("Library/Caches"))
    } else if cfg!(windows) {
        env("LOCALAPPDATA")
    } else {
        env("XDG_CACHE_HOME").or_else(|| env("HOME").map(|h| h.join(".cache")))
    };
    base.unwrap_or_else(std::env::temp_dir).join("mocida").join("device-frames")
}

/// The frame and mask PNGs of `device` in `variant`, downloading them into
/// the cache the first time. Errors when they aren't cached and can't be
/// fetched (offline).
pub fn ensure_files(device: &FrameDevice, variant: &Variant) -> Result<(PathBuf, PathBuf), String> {
    let dir = cache_dir().join(variant.path);
    let frame = dir.join("frame.png");
    let mask = dir.join("mask.png");
    for (file, name) in [(&frame, "frame.png"), (&mask, "mask.png")] {
        if !is_png(file) {
            std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
            let url = format!("{BASE_URL}{}/{name}", encode_path(variant.path));
            download(&url, file)?;
            if !is_png(file) {
                let _ = std::fs::remove_file(file);
                return Err(format!("{} {}: not a PNG at {url}", device.name, variant.name));
            }
        }
    }
    Ok((frame, mask))
}

fn is_png(path: &Path) -> bool {
    std::fs::read(path).map_or(false, |b| b.starts_with(b"\x89PNG"))
}

fn encode_path(path: &str) -> String {
    path.split('/').map(|seg| seg.replace(' ', "%20")).collect::<Vec<_>>().join("/")
}

/// Fetches `url` into `dest` with curl (macOS, Linux and Windows 10+ ship it),
/// through a temporary file so an interrupted download never looks complete.
fn download(url: &str, dest: &Path) -> Result<(), String> {
    let tmp = dest.with_extension("part");
    let out = std::process::Command::new("curl")
        .args(["-fsSL", "--max-time", "60", "-o"])
        .arg(&tmp)
        .arg(url)
        .output()
        .map_err(|e| format!("couldn't run curl to download device frames: {e}"))?;
    if !out.status.success() {
        let _ = std::fs::remove_file(&tmp);
        let why = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(format!("download failed ({url}): {why}"));
    }
    std::fs::rename(&tmp, dest).map_err(|e| format!("{}: {e}", dest.display()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_lookup_and_profile() {
        let d = lookup("iPhone 17 Pro").expect("iphone 17 pro");
        assert_eq!(d.id, "iphone-17-pro");
        assert_eq!(lookup("pixel9pro").map(|d| d.id), Some("pixel-9-pro"));
        let p = d.profile();
        assert_eq!((p.width, p.height), (402, 874));
        // 1206 px screen over 402 pt: 3 px per point; a 100 px border is 33 pt.
        assert_eq!((p.frame_screen_x, p.frame_screen_y), (33, 33));
        assert_eq!((p.frame_w, p.frame_h), (469, 941));
        assert_eq!(d.variant(Some("Cosmic Orange")).id, "cosmic-orange");
        assert_eq!(d.variant(Some("nope")).id, d.variants[0].id);
        assert!(FRAME_DEVICES.iter().any(|d| d.os == "android" && d.kind == "phone"));
    }

    #[test]
    fn paths_are_url_encoded() {
        assert_eq!(encode_path("Apple iPhone/17 Pro/Cosmic Orange"), "Apple%20iPhone/17%20Pro/Cosmic%20Orange");
    }
}
